VStack(alignment: .leading, spacing: theme.spacing.space4) {
    MonarchTextField("Full name", text: $name, error: nameError, isRequired: true)
        .textContentType(.name)
    MonarchTextField("Email", text: $email, error: emailError, isRequired: true)
        .textContentType(.username)
    MonarchPasswordInput("Password", text: $password, error: passwordError, purpose: .new, isRequired: true)
        .onSubmit(createAccount)
    MonarchPasswordStrengthMeter(password: password, rules: rules)
    MonarchTermsAcceptance(isAccepted: $acceptsTerms, documents: documents, showsRequiredError: showsTermsError)
    MonarchButton("Create account", variant: .primary, isLoading: isCreating, fullWidth: true, action: createAccount)
    HStack(spacing: theme.spacing.space1) {
        Text("Already have an account?")
            .monarchTextStyle(.bodySmall)
            .foregroundStyle(theme.colors.textMuted)
        Button("Sign in") {
            // Open sign-in.
        }
        .buttonStyle(.monarchLink())
        .monarchTextStyle(.bodySmall)
    }
    .frame(maxWidth: .infinity)
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var name = ""
@State private var email = {{email}}
@State private var password = ""
@State private var acceptsTerms = false
@State private var nameError: String?
@State private var emailError: String?
@State private var passwordError: String?
@State private var showsTermsError = false
@State private var isCreating = false
private let rules = MonarchPasswordRule.defaults
private let documents = [
    MonarchTermsDocument({{terms.0.label}}, url: URL(filePath: "/terms"), version: {{terms.0.version}}),
    MonarchTermsDocument({{terms.1.label}}, url: URL(filePath: "/privacy"), version: {{terms.1.version}}),
]

private func createAccount() {
    let trimmedEmail = email.trimmingCharacters(in: .whitespaces)
    nameError = name.trimmingCharacters(in: .whitespaces).isEmpty ? "Enter your name." : nil
    emailError = trimmedEmail.isEmpty
        ? "Enter your email address."
        : (trimmedEmail.contains("@") && trimmedEmail.contains(".") ? nil : "Enter an email address like name@example.com.")
    passwordError = password.isEmpty
        ? "Choose a password."
        : (rules.allSatisfy { $0.test(password) } ? nil : "Choose a password that meets every requirement.")
    showsTermsError = !acceptsTerms
    guard nameError == nil, emailError == nil, passwordError == nil, acceptsTerms else { return }
    isCreating = true
    Task {
        // The app creates the account. An email already in use goes in emailError.
        isCreating = false
    }
}

